rsql select season, json_extract(more('log_clubs', _more), '$.club.installed.off') off, count(*) n, round(avg(json_extract(more('log_clubs', _more), '$.club.installed.off_known')),3) known from log_clubs group by season, off order by off, season
rsql select season, json_extract(more('log_clubs', _more), '$.club.installed.front') fr, json_extract(more('log_clubs', _more), '$.club.installed.shell') sh, count(*) n, round(avg(json_extract(more('log_clubs', _more), '$.club.installed.def_known')),3) known from log_clubs group by season, fr, sh order by fr, sh, season
